const $=id=>document.getElementById(id);let demo=false,demoStart=0,denials=0,muted=false,lastNag=Date.now(),prevNight=null,serial=0,pillowIndex=0,excuseIndex=0,audio;
const messages=[['Poduszka dzwoniła.','Pyta, czy ma zacząć spotykać się z kimś innym.','To skomplikowane'],['Wykryto jeszcze jeden filmik.','Ten sam, który miał być ostatni 47 filmików temu.','To już naprawdę ostatni'],['Błąd 403: sen wymagany','Dostęp do sensownych decyzji został tymczasowo zawieszony.','Akceptuję brak rozsądku'],['Jutro Ty złożył skargę.','Treść: „No dzięki, geniuszu”. Załącznik: trzy kawy i westchnienie.','Przekaż do działu skarg'],['Kołdra rozpoczęła strajk.','Postulaty: 1. Ty. 2. Pod kołdrą. 3. Teraz.','Podejmę negocjacje'],['Aktualizacja człowieka','Dostępna wersja: wyspany. Instalacja wymaga zamknięcia oczu.','Przypomnij wczoraj'],['Czy na pewno nie śpisz?','To pytanie retoryczne. Widzimy ten kursor.','To kot klika'],['Nocna komisja orzekła:','Argument „nie chce mi się spać” uznano za uroczy, lecz nieskuteczny.','Składam odwołanie'],['Osiągnięcie odblokowane','Jeszcze nie śpisz. Nagroda: jutro też będziesz o tym wiedzieć.','Nie odbieram nagrody'],['Łóżko: wolne stanowisko','Wymagania: umiejętność leżenia. Doświadczenie mile widziane.','Aplikuję jutro']];
const excuses=[['„Ja tylko sprawdzę maila.”','Jasne. A potem jeszcze cały internet.'],['„Jestem nocnym markiem.”','Marek też już śpi.'],['„Muszę skończyć jedną rzecz.”','Czy tą rzeczą jest internet?'],['„W innej strefie jest dzień.”','Ale Twoja poduszka mieszka tutaj.'],['„Jeszcze jeden commit.”','git commit -m "idę spać"'],['„Jutro odeśpię.”','Jutro: nie przypominam sobie takiej umowy.'],['„To research.”','Film o kapibarze w wannie. Oczywiście.'],['„Nie jestem zmęczony.”','Powiedz to jeszcze raz bez ziewania.']];
const pillows=[['„Czy my się jeszcze znamy?”','Ostatnio widziana: dziś rano. Status: tęskni.'],['„Mam chłodną stronę. Dla Ciebie.”','Oferta limitowana. Kołdra już się zgodziła.'],['„Widzę, że jesteś online.”','Odczytano o 23:01. Boli bardziej niż sprężyna.'],['„Nie chcę naciskać, ale…”','Dosłownie od tego jestem. Połóż głowę.'],['„Twój kot już tu jest.”','Zajął 93% łóżka. Pozostałe 7% wciąż dostępne.']];
function now(){return demo?new Date(2026,0,1,23,0,Math.floor((Date.now()-demoStart)/1000)):new Date()}
function isNight(d){return d.getHours()>=23||d.getHours()<6}
function tick(){const d=now(),night=isNight(d),h=d.getHours();$('hh').textContent=String(h).padStart(2,'0');$('mm').textContent=String(d.getMinutes()).padStart(2,'0');$('ss').textContent=String(d.getSeconds()).padStart(2,'0');$('zone').textContent=demo?'TRYB DEMO · SYMULACJA 23:00':`CZAS LOKALNY · ${Intl.DateTimeFormat().resolvedOptions().timeZone}`;let seconds=h*3600+d.getMinutes()*60+d.getSeconds(),late=seconds>=82800?seconds-82800:seconds+3600;let remaining=82800-seconds;const fmt=s=>`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;$('countdown').textContent=night?`${fmt(late)} po dobranoc`:`DO CISZY NOCNEJ ${fmt(remaining)}`;let panic=night?Math.min(100,65+Math.floor(late/60)+denials*5):20;$('meter').style.width=panic+'%';$('levelValue').textContent=panic+'% PANIKI';$('levelName').textContent=night?(panic>90?'Kołdra przejmuje dowodzenie':'Sytuacja mocno poduszkowa'):'Spokój przed ziewnięciem';if(prevNight!==night){document.body.classList.toggle('night',night);$('heading').innerHTML=night?'Pora spać.<br>Tak, do Ciebie mówię.':'Dobry wieczór,<br>nocny marku.';$('intro').textContent=night?'Wyłącz internet. On sam nie wie, kiedy skończyć.':'Internet jutro też tu będzie. Sprawdzaliśmy.';$('status').textContent=night?'● Po 23:00. Negocjacje zakończone.':'● Jeszcze możesz tu być';if(night)lastNag=Date.now()-Number($('intensity').value)+1800;prevNight=night;}if(night&&!muted&&$('popups').checked&&Date.now()-lastNag>Number($('intensity').value)){nag();lastNag=Date.now()}}
function beep(){if(!$('sound').checked||muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(420,audio.currentTime);o.frequency.exponentialRampToValueAtTime(210,audio.currentTime+.22);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.3)}catch{}}
function nag(custom){if(muted)return;const m=custom||messages[serial%messages.length],n=serial++;while($('toasts').children.length>=3)$('toasts').firstElementChild.remove();let el=document.createElement('aside');el.className='toast';el.style.right=(18+(n%3)*24)+'px';el.style.bottom=(75+(n%3)*42)+'px';el.innerHTML='<div class="toast-head"><span>URZĄD SNU / UPOMNIENIE '+String(n+1).padStart(3,'0')+'</span><button aria-label="Zamknij upomnienie">×</button></div><h3></h3><p></p><button class="dismiss"></button>';el.querySelector('h3').textContent=m[0];el.querySelector('p').textContent=m[1];el.querySelector('.dismiss').textContent=m[2];el.querySelectorAll('button').forEach(b=>b.onclick=()=>{el.remove();$('escape').classList.toggle('hidden',!$('toasts').children.length)});$('toasts').append(el);$('escape').classList.remove('hidden');beep()}
function clearNags(){muted=true;$('popups').checked=false;$('sound').checked=false;$('toasts').replaceChildren();$('escape').classList.add('hidden')}
$('demo').onclick=()=>{demo=!demo;demoStart=Date.now();prevNight=null;muted=false;$('popups').checked=true;$('toasts').replaceChildren();$('escape').classList.add('hidden');$('demo').textContent=demo?'↶ Wróć do prawdziwej godziny':'↗ Zobacz, co będzie po 23:00';tick()};$('snooze').onclick=()=>{denials++;$('denials').textContent='Odrzucone wymówki: '+denials;muted=false;nag(['Wniosek nr '+String(denials).padStart(3,'0')+': odrzucony.',denials===1?'Pięć minut? Znamy ten numer. Zegar nie przyjmuje łapówek.':'To już '+denials+'. próba. Dział negocjacji wyszedł spać. Zostawił Ci kołdrę.','Przyjmuję do niewiadomości']);tick()};$('message').onclick=()=>{pillowIndex=(pillowIndex+1)%pillows.length;$('pillow').textContent=pillows[pillowIndex][0];$('pillowText').textContent=pillows[pillowIndex][1]};$('excuseBtn').onclick=()=>{excuseIndex=(excuseIndex+1)%excuses.length;$('excuse').textContent=excuses[excuseIndex][0];$('verdict').textContent=excuses[excuseIndex][1]};$('escape').onclick=clearNags;$('sleep').onclick=()=>{clearNags();$('goodnight').showModal()};$('back').onclick=()=>$('goodnight').close();$('popups').onchange=()=>{muted=!$('popups').checked;lastNag=Date.now();if(muted){$('toasts').replaceChildren();$('escape').classList.add('hidden')}};$('sound').onchange=()=>{if($('sound').checked){muted=false;beep()}};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('toasts').replaceChildren();$('escape').classList.add('hidden')}});tick();setInterval(tick,250);
